import sys

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]

    states = 1 << N

    # popcount[mask] = LCS length represented by this state
    popcount = [0] * states
    for mask in range(1, states):
        popcount[mask] = popcount[mask >> 1] + (mask & 1)

    # rows[mask][j] is the DP row value for prefix S[:j]
    rows = []
    for mask in range(states):
        row = [0] * (N + 1)
        cur = 0
        for j in range(1, N + 1):
            cur += (mask >> (j - 1)) & 1
            row[j] = cur
        rows.append(row)

    alphabet = [chr(ord('a') + i) for i in range(26)]

    # Precompute transitions between states for each character.
    transitions = []
    for mask in range(states):
        prev = rows[mask]
        cnt = {}

        for ch in alphabet:
            new = [0] * (N + 1)

            for j in range(1, N + 1):
                if S[j - 1] == ch:
                    new[j] = prev[j - 1] + 1
                else:
                    new[j] = max(prev[j], new[j - 1])

            next_mask = 0
            for j in range(1, N + 1):
                if new[j] != new[j - 1]:
                    next_mask |= 1 << (j - 1)

            cnt[next_mask] = cnt.get(next_mask, 0) + 1

        transitions.append(list(cnt.items()))

    # DP over the M characters of the generated string.
    dp = [0] * states
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * states
        for state, val in enumerate(dp):
            if val == 0:
                continue
            for next_state, char_count in transitions[state]:
                ndp[next_state] = (ndp[next_state] + val * char_count) % MOD
        dp = ndp

    ans = [0] * (N + 1)
    for state, val in enumerate(dp):
        ans[popcount[state]] = (ans[popcount[state]] + val) % MOD

    print(*ans)

if __name__ == "__main__":
    main()
