        m = N // d
        disc = 12 * m - 3 * d * d

        if disc < 0:
            continue

        s = isqrt(disc)
        if s * s != disc:
            continue

        num = s - 3 * d
        if num <= 0 or num % 6 != 0:
            continue

        y = num // 6
        x = y + d

        if x * x * x - y * y * y == N:
